#!/usr/bin/env python3
"""GATE 15 — FURNITURE COLLISION + LIVING NPCs (Boss QA: tumatapos sa mesa/tables,
static NPCs). WALL_GRID now includes furniture (war room table, pool table,
arcade, gym, pantry — 184 cells, A*-validated 0 fails). findPath walks to
nearest open cell when target blocked. Boss avatar + NPC shuffles are
collision-aware. NPC idle animations amplified 3-4x for visibility.
Zillion/Cody/Jax — 2026-08-25.
"""
import sys, shutil, hashlib

PATH = sys.argv[1] if len(sys.argv) > 1 else "index.html"

R1_OLD = 'const WALL_GRID = [\n  "##################################################..##########################..",\n  "############################........................##########################..",\n  "....#..###...#...##.#######...........................#..#..##....##...##...#...",\n  "......................................######....................................",\n  "...#.............................################...........................#...",\n  "...#.............................##############.##..........................#...",\n  "...#.............................#################..........................#...",\n  "...#.............................############.###...........................#...",\n  "...#.............................##.......##................................#...",\n  "...#........................................................................#...",\n  "...#........................................................................#...",\n  "...#........................................................................#...",\n  "...#........................................................................#...",\n  "...#........................................................................#...",\n  "...#........................................................................#...",\n  "...#........................................................................#...",\n  "...#........................................................................#...",\n  "...#........................................................................#...",\n  "...#........................................................................#...",\n  "...#.................................................#......................#...",\n  "...#.................................................#......................#...",\n  "...#.................................................#......................#...",\n  "...#.................................................########################...",\n  "...#.................................................#......................#...",\n  "...#.................................................#......................#...",\n  "...#.................................................#......................#...",\n  "...#.................................................#......................#...",\n  "...#.................................................#............#....#....#...",\n  "...#.................................................#......##..#####.####..#...",\n  "...#.................................................#...##..###########.#..#...",\n  "...#.....................................................###.###.######.....#...",\n  "...#......................................................######...###......#...",\n  "...#........................................................................#...",\n  "...#........................................................................#...",\n  "...#........................................................................#...",\n  "...#........................................................................#...",\n  "...#.....................................................##.#####.##........#...",\n  "...#......................................................###########.......#...",\n  "...#.......................................................#.#...#..#.......#...",\n  "................................................................................",\n  "................................................................................",\n  "................................................................................",\n  "................................................................................",\n  "................................................................................",\n  "................................................................................",\n];'
R1_NEW = 'const WALL_GRID = [\n  "##################################################..##########################..",\n  "############################........................##########################..",\n  "....#..###...#...##.#######...........................#..#..##....##...##...#...",\n  "......................................######....................................",\n  "...#.............................################...........................#...",\n  "...#.............................##############.##..........................#...",\n  "...#.............................#################..........................#...",\n  "...#.............................############.###...........................#...",\n  "...#.............................##.......##................................#...",\n  "...#........................................................................#...",\n  "...#........................................................................#...",\n  "...#........................................................................#...",\n  "...#........................................................................#...",\n  "...#........................................................................#...",\n  "...#........................................................................#...",\n  "...#........................................................................#...",\n  "...#............................##################..........................#...",\n  "...#............................##################..........................#...",\n  "...#............................##################..........................#...",\n  "...#............................##################...#......................#...",\n  "...#.................................................#......................#...",\n  "...#.................................................#......................#...",\n  "...#.................................................########################...",\n  "...#.................................................#......................#...",\n  "...#.................................................#......................#...",\n  "...#.................................................#......................#...",\n  "...#.................................................#......................#...",\n  "...#.................................................#............#....#....#...",\n  "...#.................................................#......##..#####.####..#...",\n  "...#.................................................#...##..###########.#..#...",\n  "...#..........####.......................................###.###.######.....#...",\n  "...#..........####........................................######...###......#...",\n  "...#..........####..........................................................#...",\n  "...#.....######..########...................................................#...",\n  "...#.....######..########...........................#########...............#...",\n  "...#.....######..########...........................#########...............#...",\n  "...#.....######..########...........................#############.##........#...",\n  "...#.....######.....................................#################.......#...",\n  "...#................................................##########...#..#.......#...",\n  "................................................................................",\n  "................................................................................",\n  "................................................................................",\n  "................................................................................",\n  "................................................................................",\n  "................................................................................",\n];'

REPLS = [
    ("R1-grid", R1_OLD, R1_NEW),
    ("R2-pathfind", '  if (gridBlocked(gc[0], gc[1])) return null;', '  if (gridBlocked(gc[0], gc[1])) {\n    // GATE 15: furniture-aware target — walk to nearest open cell instead of null\n    let found = null;\n    for (let d = 1; d <= 4 && !found; d++) {\n      for (let dy2 = -d; dy2 <= d && !found; dy2++) {\n        for (let dx2 = -d; dx2 <= d && !found; dx2++) {\n          if (Math.max(Math.abs(dx2), Math.abs(dy2)) !== d) continue;\n          const nx = gc[0] + dx2, ny = gc[1] + dy2;\n          if (nx >= 0 && nx < GRID_COLS && ny >= 0 && ny < GRID_ROWS && !gridBlocked(nx, ny)) found = [nx, ny];\n        }\n      }\n    }\n    if (found) { gc[0] = found[0]; gc[1] = found[1]; } else { return null; }\n  }'),
    ("R3-boss", '    if (bdist > 4) {\n      bossAvatar.x += (bdx / bdist) * bossAvatar.speed;\n      bossAvatar.y += (bdy / bdist) * bossAvatar.speed;\n      bossAvatar.isWalking = true;', '    if (bdist > 4) {\n      // GATE 15: collision-aware boss movement (no more clipping through furniture)\n      const stX = (bdx / bdist) * bossAvatar.speed;\n      const stY = (bdy / bdist) * bossAvatar.speed;\n      const tryX = bossAvatar.x + stX, tryY = bossAvatar.y + stY;\n      if (!gridBlocked(Math.floor(tryX / GRID_CW), Math.floor(tryY / GRID_CH))) {\n        bossAvatar.x = tryX; bossAvatar.y = tryY;\n      } else if (!gridBlocked(Math.floor(tryX / GRID_CW), Math.floor(bossAvatar.y / GRID_CH))) {\n        bossAvatar.x = tryX;\n      } else if (!gridBlocked(Math.floor(bossAvatar.x / GRID_CW), Math.floor(tryY / GRID_CH))) {\n        bossAvatar.y = tryY;\n      }\n      bossAvatar.isWalking = true;'),
    ("R4-shuffle-move", "      else {\n        n.facing = dx > 0 ? 'right' : 'left';\n        n.walkFrame = (stepFrame % 10 === 0) ? (n.walkFrame + 1) % 3 : n.walkFrame;\n        n.x += Math.sign(dx) * 0.85;\n      }", "      else {\n        n.facing = dx > 0 ? 'right' : 'left';\n        n.walkFrame = (stepFrame % 8 === 0) ? (n.walkFrame + 1) % 3 : n.walkFrame;\n        // GATE 15: collision-aware shuffle (bounce back if blocked)\n        const nx3 = n.x + Math.sign(dx) * 1.3;\n        if (!gridBlocked(Math.floor(nx3 / GRID_CW), Math.floor(n.y / GRID_CH))) {\n          n.x = nx3;\n        } else {\n          n.shift = -(n.shift || 0);\n        }\n      }"),
    ("R5-bob", '        const bob = n.isMoving ? (stepPhN * 1.2) : Math.sin(stepFrame * 0.03 + n.x) * 0.9;\n        const tiltN = n.isMoving ? (stepPhN * 0.05) : Math.sin(stepFrame * 0.018 + n.x) * 0.02;', '        const bob = n.isMoving ? (stepPhN * 1.6) : Math.sin(stepFrame * 0.05 + n.x) * 3.2;\n        const tiltN = n.isMoving ? (stepPhN * 0.06) : Math.sin(stepFrame * 0.032 + n.x) * 0.055;'),
    ("R5b-frame", '        const frame = n.isMoving ? (n.walkFrame % 3) : (Math.floor(stepFrame / 16) % 3);', '        const frame = n.isMoving ? (n.walkFrame % 3) : (Math.floor(stepFrame / 12) % 3);'),
    ("R6-shuffle-params", '      } else if (roll < 0.75 && !n.isMoving) {\n        // small shuffle 24px to the side then back\n        n.shift = (Math.random() < 0.5 ? -1 : 1) * 24;\n        n.isMoving = true;\n        n.timer = 110 + Math.floor(Math.random() * 160);', '      } else if (roll < 0.85 && !n.isMoving) {\n        // GATE 15: bigger, more frequent shuffle (44px) — NPCs clearly alive\n        n.shift = (Math.random() < 0.5 ? -1 : 1) * 44;\n        n.isMoving = true;\n        n.timer = 90 + Math.floor(Math.random() * 120);'),
]


def main():
    html = open(PATH, encoding="utf-8").read()
    orig_len = len(html)

    if "GATE 15: FURNITURE" in html or "GATE 15: collision-aware" not in html and "collision-aware boss" in html:
        pass
    if "collision-aware boss" in html:
        print("ALREADY PATCHED — abort (idempotent guard)")
        return 1

    for name, anchor, new in REPLS:
        n = html.count(anchor)
        if n != 1:
            print(f"ANCHOR {name} count={n} (expected 1) — ABORT, file untouched")
            return 1
        html = html.replace(anchor, new, 1)

    shutil.copyfile(PATH, PATH + ".bak_pre_g15")

    open(PATH, "w", encoding="utf-8").write(html)
    new_len = len(html)
    print(f"PATCHED OK: {orig_len:,} -> {new_len:,} chars (+{new_len - orig_len:,})")
    print("checks: grid-rows x" + str(html.count('\"') if False else sum(1 for l in R1_NEW.split(chr(10)) if l.strip().startswith('  \"'))) 
          + " collision x" + str(html.count("GATE 15:"))
          + " nearest-open x" + str(html.count("nearest open cell"))
          + " shuffle44 x" + str(html.count("* 44")))
    print("sha256:", hashlib.sha256(open(PATH, "rb").read()).hexdigest())
    return 0


if __name__ == "__main__":
    sys.exit(main())
